add_action( 'woocommerce_after_shipping_rate', 'perfectpixel_shipping_rate_description', 10, 2 );

function perfectpixel_shipping_rate_description( $rate, $index ) {
	// Rate ID (e.g. "flat_rate:3") or method ID (e.g. "local_pickup") => description.
	$descriptions = array(
		'free_shipping' => 'Παράδοση σε 2-4 εργάσιμες.',
		'local_pickup'  => 'Παραλαβή από το κατάστημα την επόμενη εργάσιμη.',
		'flat_rate'     => 'Παράδοση σε 1-3 εργάσιμες με courier.',
	);

	$text = $descriptions[ $rate->get_id() ] ?? ( $descriptions[ $rate->get_method_id() ] ?? '' );
	if ( '' !== $text ) {
		echo '<p class="perfectpixel-shipping-description" style="margin:.25em 0 0;font-size:.875em;opacity:.8">' . esc_html( $text ) . '</p>';
	}
}
